  for(const faction of['cartographers','forgers']as const){
    const plain=await setup(faction),boosted={...plain,store:new MemoryStore()};boosted.store.record=structuredClone(plain.store.record);const normal=await confirm(plain,{type:'craft.start',playerId:plain.id,recipeId:'plank',qty:1}),fast=await confirm(boosted,{type:'craft.start',playerId:plain.id,recipeId:'plank',qty:1,useTestBoost:true});const a=normal.view.jobs[0],b=fast.view.jobs[0],base=faction==='forgers'?270:300,saved=Math.floor(base/5);
    assert.equal(fast.quote.boost!.baseSeconds,base);assert.equal(fast.quote.boost!.durationSeconds,base-saved);assert.equal(fast.quote.boost!.savedSeconds,saved);assert.equal(b.endsAt-b.startsAt,(base-saved)*1000);assert.deepEqual(a.costs,b.costs);assert.deepEqual(normal.quote.changes,fast.quote.changes);assert.deepEqual(normal.quote.expectedOutputs,fast.quote.expectedOutputs);assert.equal(fast.view.boosts.usedSeconds,saved);assert.equal(fast.view.boosts.remainingSeconds,1800-saved);
    const outA=await readMvpView(plain.store,plain.owner,plain.id,a.endsAt),outB=await readMvpView(boosted.store,boosted.owner,boosted.id,b.endsAt);
    assert.equal(outA.jobs.find(job=>job.id===a.id)!.status,'completed');assert.equal(outB.jobs.find(job=>job.id===b.id)!.status,'completed');
    const normalizeOwnOutput=(inventory:Player['inventory'],jobId:string)=>{
      const output=inventory.filter(lot=>lot.itemId==='plank');assert.equal(output.length,1);assert.equal(output[0].provenance.source,`recipe:plank:${jobId}`);
      // Separate confirmed operations have distinct IDs; normalize only this
      // verified output-to-job reference, preserving every economic field.
      return inventory.map(lot=>lot===output[0]?{...lot,provenance:{...lot.provenance,source:'recipe:plank:OWN_COMPLETED_JOB'}}:lot);
    };
    assert.deepEqual(normalizeOwnOutput(outA.player!.inventory,a.id),normalizeOwnOutput(outB.player!.inventory,b.id));assert.equal(outA.activity!.progression.xp,outB.activity!.progression.xp);assert.equal(outB.activity!.progression.xp,10);assert.equal(outB.player!.inventory.find(l=>l.itemId==='plank')!.bound,true);
  }
});

